set -eu
docker inspect gace-createvdobot-videobot-poll-1 --format '{{.State.Running}}' | grep -qx true
docker exec -i gace-createvdobot-videobot-poll-1 node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const target=-1004396338340;
const file=process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE;
if(typeof file!=='string'||!file.startsWith('/run/secrets/'))throw Error('BOT_TOKEN_MOUNT_UNAVAILABLE');
const token=readFileSync(file,'utf8').trim();
async function call(method,data={}) {
 const res=await fetch('https://api.telegram.org/bot'+token+'/'+method,{
  method:'POST',headers:{'content-type':'application/json'},
  body:JSON.stringify(data),signal:AbortSignal.timeout(16000)});
 const j=await res.json();
 if(!j.ok)return {ok:false,error_code:j.error_code||null};
 return {ok:true,result:j.result};
}
try{
 const me=await call('getMe');
 if(!me.ok||!Number.isSafeInteger(me.result?.id))throw Error('BOT_IDENTITY_UNAVAILABLE');
 const chat=await call('getChat',{chat_id:target});
 const member=chat.ok?await call('getChatMember',{chat_id:target,user_id:me.result.id}):null;
 console.log(JSON.stringify({
  target:target,chatConfirmed:chat.ok&&chat.result?.id===target,
  chatType:chat.ok?chat.result?.type:null,
  chatTitle:chat.ok?chat.result?.title:null,
  memberStatus:member?.ok?member.result?.status:null,
  canInviteUsers:member?.ok?member.result?.can_invite_users===true:null,
  botAdmin:member?.ok?['administrator','creator'].includes(member.result?.status):false,
  apiError:chat.ok?null:chat.error_code,
  memberError:member&&!member.ok?member.error_code:null
 },null,2));
}catch(err){console.log('CHANNEL_LOOKUP_FAILED='+String(err?.name||'UNKNOWN'));process.exitCode=2}
